<script setup lang="ts">
import {computed,onBeforeUnmount,ref,watch} from 'vue';
import type {Session} from '../FleetAndDocuments/contracts';
import {getSession,refreshCsrf} from '../FleetAndDocuments/api';
import {request,failure,paginated} from '../Administration/api';
import {registrationDate} from '../FleetAndDocuments/presentation';
import {labels as stateLabels} from '../TransportAndDispatch/presentation';
import {instant,localInstant} from '../Workshop/presentation';
import {cacheTrip,cachedTrips,captures,newCapture,saveCaptures,synchronize} from '../DriverPortal/offline';
import type {Capture} from '../DriverPortal/offline';
import type {DriverTrip,DriverExpense,DriverReport,DriverReading} from '../DriverPortal/contracts';
const props=defineProps<{session:Session|null}>();const emit=defineEmits<{denied:[error:unknown];session:[actor:Session];lock:[locked:boolean]}>();
const queue=ref<Capture[]>([]),syncing=ref(false),connection=ref(navigator.onLine),localError=ref('');
let syncTimer:ReturnType<typeof setInterval>|undefined;
async function refreshQueue():Promise<void>{const actor=props.session?.id;if(actor){const rows=await captures(actor);if(props.session?.id===actor)queue.value=rows;}}
async function sync(manual=false):Promise<void>{
 const actor=props.session?.id;if(!actor||syncing.value||!connection.value)return;
 const confirmed=new Set(queue.value.filter(c=>c.status==='sincronizado').map(c=>c.id));
 syncing.value=true;success.value='';
 try{
  await synchronize(actor,refreshQueue,manual);await refreshQueue();
  if(props.session?.id===actor){
   const count=queue.value.filter(c=>c.status==='sincronizado'&&!confirmed.has(c.id)).length;
   if(count)success.value=`${count} ${count===1?'registro confirmado':'registros confirmados'} por el servidor en este intento. Los gastos siguen sujetos a decisión administrativa.`;
  }
 }catch(e){report(e);}finally{syncing.value=false;}
 if(props.session?.id===actor&&navigator.onLine){await load();if(selected.value)await details(selected.value.id);}
}
function connectivity():void{connection.value=navigator.onLine;if(connection.value)void sync();}
window.addEventListener('online',connectivity);window.addEventListener('offline',connectivity);
syncTimer=setInterval(()=>{if(navigator.onLine&&queue.value.some(c=>c.status==='pendiente'||c.status==='sincronizando'))void sync();},15000);
const trips=ref<DriverTrip[]>([]),selected=ref<DriverTrip|null>(null),expenses=ref<DriverExpense[]>([]),records=ref<{reports:DriverReport[];odometer:DriverReading[]}>({reports:[],odometer:[]});
const historyExpenses=ref<DriverExpense[]>([]),historyPage=ref(1),historyLast=ref(1);
const loading=ref(false),busy=ref(false),error=ref(''),success=ref(''),fields=ref<Record<string,string[]>>({}),page=ref(1),last=ref(1);let generation=0;
const locked=computed(()=>busy.value),driver=computed(()=>props.session?.roles.some(r=>['driver','administrator'].includes(r))??false);
const newReceipt=ref<File|null>(null),fileGeneration=ref(0),newFileGeneration=ref(0);
const date=ref(localInstant()),observation=ref(''),reportType=ref('information'),reading=ref(''),readingType=ref('initial'),reason=ref(''),concept=ref(''),category=ref(''),amount=ref(''),currency=ref('CRC'),description=ref(''),receipt=ref<File|null>(null),receiptExpense=ref('');
watch(locked,value=>emit('lock',value),{immediate:true});
function report(e:unknown):void{const p=failure(e);error.value=p.message;fields.value=p.fields;if([401,403,419].includes(p.status)){trips.value=[];selected.value=null;expenses.value=[];records.value={reports:[],odometer:[]};emit('denied',p);}}
async function load(target=page.value):Promise<void>{if(loading.value||!props.session||!driver.value)return;const actor=props.session.id;const current=++generation;loading.value=true;error.value='';try{const result=await paginated<DriverTrip>(`/transport/my-trips?page=${target}`);if(current!==generation)return;trips.value=result.data;page.value=result.meta.current_page;last.value=result.meta.last_page;for(const trip of result.data)await cacheTrip(actor,trip,[]);}catch(e){if(current===generation){if(failure(e).status===0&&props.session){const cached=await cachedTrips(props.session.id);if(current!==generation)return;trips.value=cached.map(c=>c.trip);error.value='Sin conexión: viajes previamente consultados (máximo 24 horas).';}else report(e);}}finally{if(current===generation)loading.value=false;}}
async function details(id:string):Promise<void>{if(loading.value||busy.value)return;const current=++generation;loading.value=true;error.value='';try{const [trip,costs]=await Promise.all([request<DriverTrip>(`/transport/my-trips/${id}`),paginated<DriverExpense>(`/expenses?trip_id=${id}&per_page=100`)]);if(current!==generation)return;selected.value=trip;expenses.value=costs.data;records.value={reports:trip.my_reports??[],odometer:trip.my_odometer??[]};if(props.session)await cacheTrip(props.session.id,trip,costs.data);}catch(e){if(current===generation){if(failure(e).status===0&&props.session){const cached=(await cachedTrips(props.session.id)).find(c=>c.trip.id===id);if(current!==generation)return;if(cached){selected.value=cached.trip;expenses.value=cached.expenses;records.value={reports:[],odometer:[]};}else error.value='Consulta este viaje con conexión antes de capturar offline.';}else report(e);}}finally{if(current===generation)loading.value=false;}}
async function ownHistory(target=1):Promise<void>{if(loading.value||busy.value||!props.session)return;const current=++generation;loading.value=true;try{const [history,costs]=await Promise.all([request<{reports:DriverReport[];odometer:DriverReading[];meta?:{current_page:number;last_page:number}}>(`/transport/my-records?page=${target}&per_page=25`),paginated<DriverExpense>(`/expenses?mine=1&page=${target}&per_page=25`)]);if(current!==generation)return;records.value=history;historyExpenses.value=costs.data;historyPage.value=target;historyLast.value=Math.max(history.meta?.last_page??1,costs.meta.last_page);}catch(e){if(current===generation)report(e);}finally{if(current===generation)loading.value=false;}}
watch(()=>props.session?`${props.session.id}:${props.session.roles.slice().sort().join('|')}`:'',async()=>{const actor=props.session;generation++;trips.value=[];selected.value=null;expenses.value=[];records.value={reports:[],odometer:[]};historyExpenses.value=[];queue.value=[];observation.value='';reading.value='';reason.value='';concept.value='';category.value='';amount.value='';description.value='';receipt.value=null;newReceipt.value=null;fileGeneration.value++;newFileGeneration.value++;receiptExpense.value='';success.value='';fields.value={};historyPage.value=1;historyLast.value=1;loading.value=false;if(actor){try{await refreshQueue();await load(1);if(navigator.onLine&&queue.value.some(c=>c.status==='pendiente'||c.status==='sincronizando'))void sync();}catch(e){localError.value='No se pudo abrir el almacenamiento local. No captures hasta recuperar espacio o acceso.';}}},{immediate:true});
async function command(title:string,path:string,body:Record<string,unknown>,file:File|null=null):Promise<void>{
 if(locked.value||!props.session||!driver.value)return;
 success.value='';
 const proof=file??(path==='/expenses'?newReceipt.value:null);if(proof&&(proof.size<1||proof.size>10000000||!['application/pdf','image/jpeg','image/png'].includes(proof.type))){error.value='Comprobante PDF/JPG/PNG de hasta 10.000.000 bytes.';return;}
 if(!confirm(`${title}. ¿Confirmas los datos? La captura local no es una confirmación del servidor.`))return;
 const actor=props.session.id;busy.value=true;error.value='';localError.value='';
 try{
  const operation=newCapture(actor,title,path,{...body,...(selected.value?.offline_context?{expected_trip_context:selected.value.offline_context}:{})},file),batch=[operation];
  if(path==='/expenses'&&newReceipt.value)batch.push(newCapture(actor,'Comprobante del gasto local','/expenses/local/receipts',selected.value?.offline_context?{expected_trip_context:selected.value.offline_context}:{},newReceipt.value,operation.id));
  await saveCaptures(batch);
  await refreshQueue();success.value='Captura guardada localmente, pendiente de confirmación.';
  if(path.endsWith('/reports'))observation.value='';
  else if(path.endsWith('/odometer')){reading.value='';reason.value='';}
  else if(path==='/expenses'){concept.value='';category.value='';amount.value='';description.value='';newReceipt.value=null;newFileGeneration.value++;}
  else if(path.endsWith('/receipts')){receipt.value=null;receiptExpense.value='';fileGeneration.value++;}
 }catch(e){localError.value='No se pudo guardar toda la captura. Revisa la cola y el espacio disponible; conserva los datos y comprobantes originales.';}
 finally{busy.value=false;}
 if(navigator.onLine)await sync(true);
}
async function retry():Promise<void>{await sync(true);}
async function recover():Promise<void>{try{await refreshCsrf();const actor=await getSession();emit('session',actor);}catch(e){report(e);}}
function downloadCapture(capture:Capture):void{const blob=new Blob([JSON.stringify({...capture,file:capture.file?{name:capture.file.name,type:capture.file.type,size:capture.file.size}:null},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`captura-${capture.id}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function downloadProof(capture:Capture):void{if(!capture.file)return;const url=URL.createObjectURL(capture.file);const a=document.createElement('a');a.href=url;a.download=capture.file.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function addReport():void{if(selected.value)void command('Registrar reporte',`/transport/my-trips/${selected.value.id}/reports`,{type:reportType.value,information:{observation:observation.value},occurred_at:instant(date.value)});}
function addReading():void{const assignment=selected.value?.assets.find(a=>a.type==='tractor_unit');if(selected.value&&assignment)void command('Registrar kilometraje',`/transport/my-trips/${selected.value.id}/odometer`,{tractor_assignment_id:assignment.id,reading_type:readingType.value,reading_value:reading.value,reason:reason.value,occurred_at:instant(date.value)});}
function addExpense():void{if(selected.value)void command('Registrar gasto pendiente','/expenses',{trip_id:selected.value.id,concept:concept.value,category:category.value,amount:amount.value,currency:currency.value,description:description.value||null,occurred_at:instant(date.value)});}
function fileChanged(event:Event):void{receipt.value=(event.target as HTMLInputElement).files?.[0]??null;}
function unload(e:BeforeUnloadEvent):void{if(locked.value){e.preventDefault();e.returnValue='';}}window.addEventListener('beforeunload',unload);onBeforeUnmount(()=>{generation++;clearInterval(syncTimer);window.removeEventListener('online',connectivity);window.removeEventListener('offline',connectivity);window.removeEventListener('beforeunload',unload);emit('lock',false);});
</script>
<template><section class="driver-portal space-y-4"><h2 class="text-xl font-semibold">Mis viajes asignados</h2><p class="notice-info">Capturas offline disponibles para viajes consultados en este dispositivo durante 24 horas. Una captura local no confirma un registro. Los reportes nunca inician, finalizan ni cierran oficialmente un viaje. La sincronización automática requiere mantener la aplicación abierta. Los gastos confirmados siguen pendientes de aprobación; aprobar no significa desembolsar ni reembolsar.</p><p v-if="error" role="alert" class="notice-error">{{error}}</p><ul v-if="Object.keys(fields).length" role="alert" class="notice-error"><template v-for="(messages,key) in fields" :key="key"><li v-for="message in messages" :key="message">{{key}}: {{message}}</li></template></ul><p v-if="success" role="status" class="notice-success">{{success}}</p><button v-if="!session" class="btn-secondary" :disabled="busy" @click="recover">Comprobar sesión y recuperar operación</button><p v-if="localError" role="alert" class="notice-error">{{localError}}</p><p role="status" :class="connection?'notice-info':'notice-error'" aria-live="polite">{{connection?'Conexión disponible; se verificará el servidor.':'Sin conexión'}} · {{queue.filter(c=>c.status!=='sincronizado').length}} capturas sin confirmar</p><section v-if="session&&queue.length" class="panel space-y-3"><h3 class="font-semibold">Capturas de este dispositivo</h3><button class="btn-primary" :disabled="syncing||busy||!connection||!queue.some(c=>c.status==='pendiente'||c.status==='sincronizando')" @click="retry">{{syncing?'Sincronizando…':'Sincronizar pendientes'}}</button><p v-if="!connection" class="notice-info">Para sincronizar, recupera conexión y mantén abierta esta aplicación. No se envían registros con la aplicación cerrada.</p>
<dl class="grid grid-cols-2 gap-2 sm:grid-cols-3" aria-label="Resumen de sincronización"><div v-for="item in [{state:'pendiente',label:'Pendientes'},{state:'sincronizando',label:'Enviando'},{state:'sincronizado',label:'Sincronizadas'},{state:'en conflicto',label:'Con conflicto'},{state:'rechazado',label:'Rechazadas'}]" :key="item.state" class="rounded border border-blue-200 p-2"><dt>{{item.label}}</dt><dd class="font-semibold">{{queue.filter(c=>c.status===item.state).length}}</dd></div></dl>
<p>No se borran capturas rechazadas o en conflicto. Conserva o descarga su contenido para revisión; no se sobrescribe el servidor.</p><article v-for="capture in queue" :key="capture.id" class="border-b pb-3 break-words"><p>{{capture.title}} · <strong class="inline-block rounded px-2 py-1" :class="capture.status==='sincronizado'?'bg-green-100 text-green-900':capture.status==='en conflicto'||capture.status==='rechazado'?'bg-red-100 text-red-900':capture.status==='sincronizando'?'bg-blue-100 text-blue-900':'bg-amber-100 text-amber-900'">{{capture.status}}</strong></p><p>{{capture.message}}</p><p v-if="capture.status==='en conflicto'||capture.status==='rechazado'" class="text-sm">Requiere revisión con oficina. Se conservan los datos; Sincronizar no modifica ni reenvía este registro automáticamente.</p><p class="text-sm">Clave: {{capture.id}}</p><details><summary class="cursor-pointer text-blue-800 underline">Ver datos de esta captura</summary><pre class="whitespace-pre-wrap text-sm">{{JSON.stringify(capture.body,null,2)}}</pre></details><button class="btn-secondary" @click="downloadCapture(capture)">Descargar captura</button><button v-if="capture.file" class="btn-secondary" @click="downloadProof(capture)">Descargar comprobante local</button></article></section><template v-if="session&&driver"><div class="flex flex-wrap gap-3"><button class="btn-secondary" :disabled="loading||busy" @click="load()">Actualizar viajes</button><button class="btn-secondary" :disabled="loading||busy" @click="ownHistory()">Consultar mis registros históricos</button></div><p v-if="loading" role="status">Consultando registros…</p><p v-else-if="!trips.length">No hay viajes asignados vigentes.</p><div class="grid gap-3 md:grid-cols-2"><article v-for="trip in trips" :key="trip.id" class="panel space-y-2"><h3 class="font-semibold">{{trip.route.name}} · {{trip.product}}</h3><p>{{trip.route.origin}} → {{trip.route.destination}}</p><p class="break-all text-sm">Viaje {{trip.id}}</p><p>{{stateLabels[trip.execution_status]??trip.execution_status}} · {{stateLabels[trip.administrative_status]??trip.administrative_status}}</p><p>Programación: {{trip.scheduled_start_at?registrationDate(trip.scheduled_start_at):'Sin fecha registrada'}}</p><p v-for="asset in trip.assets" :key="asset.code">{{asset.type==='tanker'?'Cisterna':'Cabezal'}}: {{asset.code}}</p><button class="btn-primary" :disabled="loading||locked" @click="details(trip.id)">Consultar viaje y registrar información</button></article></div><div class="flex flex-wrap items-center gap-3"><button class="btn-secondary" :disabled="loading||busy||page<=1" @click="load(page-1)">Anterior</button><span>Página {{page}} de {{last}}</span><button class="btn-secondary" :disabled="loading||busy||page>=last" @click="load(page+1)">Siguiente</button></div><section v-if="selected" class="panel space-y-5"><h3 class="text-xl font-semibold">Operación del viaje: {{selected.route.name}}</h3><p>La asignación vigente y los permisos se validan nuevamente al confirmar cada registro.</p><label class="block">Fecha y hora del registro (Costa Rica)<input v-model="date" class="field" type="datetime-local" step="1" :disabled="locked" required></label><div class="grid gap-5 lg:grid-cols-2"><form class="space-y-3" @submit.prevent="addReport"><h4 class="font-semibold">Eventos y observaciones</h4><label class="block">Tipo de reporte<select aria-label="Tipo de reporte" v-model="reportType" class="field" :disabled="locked"><option value="information">Información</option><option value="incident">Incidencia o avería</option><option value="completion_report">Reporte informativo de terminación</option></select></label><label class="block">Observación<textarea v-model="observation" class="field" maxlength="2000" required :disabled="locked"></textarea></label><button class="btn-primary" :disabled="locked||!date">Registrar reporte</button></form><form class="space-y-3" @submit.prevent="addReading"><h4 class="font-semibold">Lectura de odómetro</h4><label class="block">Tipo de lectura<select aria-label="Tipo de lectura" v-model="readingType" class="field" :disabled="locked"><option value="initial">Inicial</option><option value="final">Final</option></select></label><label class="block">Kilometraje<input v-model="reading" class="field" inputmode="decimal" pattern="[0-9]+(\.[0-9]{1,2})?" required :disabled="locked"></label><label class="block">Motivo de lectura<input v-model="reason" class="field" maxlength="2000" required :disabled="locked"></label><button class="btn-primary" :disabled="locked||!date||!selected.assets.some(a=>a.type==='tractor_unit')">Registrar kilometraje</button></form></div><form class="space-y-3 border-t pt-4" @submit.prevent="addExpense"><h4 class="font-semibold">Gasto del viaje</h4><p class="text-sm">Se registra pendiente de decisión del administrador. El comprobante local se conserva y se envía después de confirmar el gasto, sin crear otro gasto.</p><div class="grid gap-3 sm:grid-cols-2"><label>Concepto<input v-model="concept" class="field" required maxlength="255" :disabled="locked"></label><label>Categoría<input v-model="category" class="field" required maxlength="255" :disabled="locked"></label><label>Monto<input v-model="amount" class="field" inputmode="decimal" pattern="[0-9]+(\.[0-9]{1,2})?" required :disabled="locked"></label><label>Moneda<select aria-label="Moneda" v-model="currency" class="field" :disabled="locked"><option>CRC</option><option>USD</option></select></label></div><label class="block">Descripción<textarea v-model="description" class="field" :disabled="locked"></textarea></label><label class="block">Comprobante del nuevo gasto (opcional, PDF/JPG/PNG, máximo 10 MB)<input type="file" class="field" :key="'new-proof-'+newFileGeneration" accept="application/pdf,image/jpeg,image/png" :disabled="locked" @change="newReceipt=($event.target as HTMLInputElement).files?.[0]??null"></label><button class="btn-primary" :disabled="locked||!date">Registrar gasto pendiente</button></form><section class="space-y-3"><h4 class="font-semibold">Mis gastos de este viaje</h4><p v-if="!expenses.length">No hay gastos registrados.</p><article v-for="expense in expenses" :key="expense.id" class="rounded border border-blue-200 p-3"><p>{{expense.concept}} · {{expense.currency}} {{expense.amount}} · {{expense.status==='approved'?'Aprobado':expense.status==='rejected'?'Rechazado':'Pendiente'}}</p><a v-for="proof in expense.receipts" :key="proof.id" :href="`/api/expenses/receipts/${proof.id}/download`" class="text-blue-800 underline block">Descargar comprobante autorizado</a></article><form v-if="expenses.length" class="space-y-3" @submit.prevent="receipt&&receiptExpense&&command('Adjuntar comprobante',`/expenses/${receiptExpense}/receipts`,{},receipt)"><label class="block">Gasto para adjuntar comprobante<select aria-label="Gasto para adjuntar comprobante" v-model="receiptExpense" class="field" required :disabled="locked"><option value="">Seleccionar gasto</option><option v-for="expense in expenses" :key="expense.id" :value="expense.id">{{expense.concept}} · {{expense.currency}} {{expense.amount}}</option></select></label><label class="block">Comprobante PDF, JPG o PNG (máximo 10 MB)<input type="file" class="field" :key="'proof-'+fileGeneration" accept="application/pdf,image/jpeg,image/png" required :disabled="locked" @change="fileChanged"></label><button class="btn-primary" :disabled="locked||!receipt||!receiptExpense">Adjuntar comprobante privado</button></form></section></section><section class="panel space-y-3"><h3 class="font-semibold">Historial de mis registros</h3><article v-for="item in records.reports" :key="item.id" class="border-b pb-2"><p>{{item.type==='incident'?'Incidencia':item.type==='completion_report'?'Reporte informativo de terminación':'Información'}} · {{registrationDate(item.occurred_at)}}</p><p class="whitespace-pre-wrap break-words">{{item.information.observation}}</p></article><p v-for="item in records.odometer" :key="item.id">{{item.reading_type==='initial'?'Inicial':'Final'}}: {{item.reading_value}} km · {{registrationDate(item.occurred_at)}} · {{item.reason}}</p><p v-if="!records.reports.length&&!records.odometer.length">No hay registros propios para mostrar.</p><h4 class="font-semibold">Historial de mis gastos</h4><article v-for="expense in historyExpenses" :key="expense.id" class="border-b py-2"><p>{{expense.concept}} · {{expense.currency}} {{expense.amount}} · {{expense.status==='approved'?'Aprobado':expense.status==='rejected'?'Rechazado':'Pendiente'}}</p><a v-for="proof in expense.receipts" :key="proof.id" :href="`/api/expenses/receipts/${proof.id}/download`" class="text-blue-800 underline block">Descargar comprobante histórico autorizado</a></article><div class="flex flex-wrap items-center gap-3"><button class="btn-secondary" :disabled="loading||busy||historyPage<=1" @click="ownHistory(historyPage-1)">Registros anteriores</button><span>Página histórica {{historyPage}} de {{historyLast}}</span><button class="btn-secondary" :disabled="loading||busy||historyPage>=historyLast" @click="ownHistory(historyPage+1)">Más registros</button></div></section></template></section></template>

<style scoped>
.driver-portal {min-width:0;overflow-wrap:anywhere;}
.driver-portal :deep(.panel),.driver-portal :deep(form),.driver-portal :deep(.grid > *) {min-width:0;}
.driver-portal :deep(.field) {min-width:0;max-width:100%;box-sizing:border-box;}
.driver-portal :deep(button) {max-width:100%;white-space:normal;}
.driver-portal pre {min-width:0;max-width:100%;overflow-wrap:anywhere;white-space:pre-wrap;}
</style>
